import fs from 'node:fs/promises';
import { assemble } from './hairline/build.mjs';
const figure = await fs.readFile('figures/pin-field.js', 'utf8');
const kernel = await fs.readFile('scripts/hairline/kernel.js', 'utf8');
await fs.mkdir('public/figures', { recursive: true });
await fs.writeFile('public/figures/hairline-pin-field.html', assemble(figure));
// The vendor kernel is copied verbatim. Only the registration adapter is ours.
await fs.writeFile(
  'src/components/figures/pin-field.generated.mjs',
  '// Generated by scripts/build-hairline.mjs. Do not edit.\n' +
    kernel +
    '\nlet definition;\nfunction hairline(value) { definition = value; }\n' +
    figure +
    '\nexport { HL, definition };\n',
);
console.log('Built the standalone Hairline page and application module.');
